use segment_tree::SegmentTree;

#[test]
fn test_build_and_query() {
    let data = vec![1, 3, 5, 7, 9, 11];
    let st = SegmentTree::new(&data);
    assert_eq!(st.query(0, 5), 36); // sum of all
    assert_eq!(st.query(1, 3), 15); // 3+5+7
    assert_eq!(st.query(0, 0), 1);  // single element
}

#[test]
fn test_update() {
    let data = vec![1, 3, 5, 7, 9];
    let mut st = SegmentTree::new(&data);
    st.update(2, 10); // change index 2 from 5 to 10
    assert_eq!(st.query(0, 4), 30); // 1+3+10+7+9
    assert_eq!(st.query(1, 3), 20); // 3+10+7
}

#[test]
fn test_single_element() {
    let st = SegmentTree::new(&[42]);
    assert_eq!(st.query(0, 0), 42);
}
